// Compact Russian (Snowball) + tiny English stemmers. Zero dependencies.
//
// Exact port of B's `compiler/src/stem.py` (17-140) — the ground truth for the
// M2 merge (MERGE_PLAN §2.1). Suffix lists, their ORDER, the rv region and the
// first-match-wins behaviour are reproduced verbatim so our node output matches
// B's Python byte-for-byte.
//
// NOTE: MERGE_PLAN §2.1 prints abbreviated/incorrect suffix lists (and wrong
// golden vectors). stem.py wins: golden vectors in test/stem.test.mjs were
// generated by executing B's stem.py once during L1a.

const VOWEL = 'аеиоуыэюяё';

// Entries are either a plain suffix string or [suffix, preEndings]. The pre
// list models Snowball's "preceding letter must be а/я" groups; when it fires
// the base loses one more char (the а/я) after the suffix is stripped.
const PERFECTIVE_GERUND = [['в',['а','я']],['вши',['а','я']],['вшись',['а','я']],['ив',[]],['ыв',[]],['ивши',[]],['ывши',[]],['ившись',[]],['ывшись',[]]];
const ADJ = ['ее','ие','ые','ое','ими','ыми','ей','ий','ый','ой','ем','им','ым','ом','его','ого','ему','ому','их','ых','ую','юю','ая','яя','ою','ею'];
const PARTICIPLE = [['ем',['а','я']],['нн',['а','я']],['вш',['а','я']],['ющ',['а','я']],['щ',['а','я']],['ивш',[]],['ывш',[]],['ующ',[]]];
const REFLEXIVE = ['ся','сь'];
const VERB = [['ла',['а','я']],['на',['а','я']],['ете',['а','я']],['йте',['а','я']],['ли',['а','я']],['й',['а','я']],['л',['а','я']],['ем',['а','я']],['н',['а','я']],['ло',['а','я']],['но',['а','я']],['ет',['а','я']],['ют',['а','я']],['ны',['а','я']],['ть',['а','я']],['ешь',['а','я']],['нно',['а','я']],['ило',[]],['ыло',[]],['ено',[]],['ует',[]],['уют',[]],['ит',[]],['ыт',[]],['ены',[]],['ить',[]],['ыть',[]],['ишь',[]],['ую',[]],['ат',[]],['ят',[]],['ил',[]],['ыл',[]],['им',[]],['ым',[]],['ен',[]],['ей',[]]];
const NOUN = ['а','ев','ов','ие','ье','е','иями','ями','ами','еи','ии','и','ией','ей','ой','ий','й','иям','ям','ием','ем','ам','ом','о','у','ах','иях','ях','ы','ь','ию','ью','ю','ия','ья','я'];
const SUPERLATIVE = ['ейш','ейше'];
const DERIVATIONAL = ['ост','ость'];

function rv(word){for(let i=0;i<word.length;i++)if(VOWEL.includes(word[i]))return i+1;return word.length;}

// First suffix whose remaining base keeps length >= region wins. Pre-checked
// suffixes additionally require the base to end in one of the pre letters,
// after which that letter is dropped (base = base[:-1]).
function tryEnd(stem,endings,region){
  for(const pair of endings){
    let end,pre;
    if(Array.isArray(pair)&&pair.length===2&&Array.isArray(pair[1])){end=pair[0];pre=pair[1];}
    else{end=pair;pre=[];}
    if(!stem.endsWith(end))continue;
    let base=stem.slice(0,stem.length-end.length);
    if(base.length<region)continue;
    if(pre.length){
      if(!pre.some(p=>base.endsWith(p)))continue;
      base=base.slice(0,-1);
    }
    return [base,true];
  }
  return [stem,false];
}

export function stemRu(word){
  let w=word.toLowerCase().replace(/ё/g,'е');
  if(w.length<4)return w;
  const region=rv(w);
  let s=w,ok;
  [s,ok]=tryEnd(w,PERFECTIVE_GERUND,region);
  if(!ok){
    for(const r of REFLEXIVE){if(s.endsWith(r)&&s.length-r.length>=region){s=s.slice(0,-r.length);break;}}
    let s2,ok2;
    [s2,ok2]=tryEnd(s,ADJ,region);
    if(ok2){
      s=s2;
      let s3,ok3;
      [s3,ok3]=tryEnd(s,PARTICIPLE,region);
      if(ok3)s=s3;
    }else{
      [s2,ok2]=tryEnd(s,VERB,region);
      if(ok2)s=s2;
      else[s]=tryEnd(s,NOUN,region);
    }
  }
  if(s.endsWith('и')&&s.length-1>=region)s=s.slice(0,-1);
  for(const d of DERIVATIONAL){if(s.endsWith(d)&&s.length-d.length>=region){s=s.slice(0,-d.length);break;}}
  if(s.endsWith('нн'))s=s.slice(0,-1);
  for(const sup of SUPERLATIVE){if(s.endsWith(sup)&&s.length-sup.length>=region){s=s.slice(0,-sup.length);if(s.endsWith('нн'))s=s.slice(0,-1);break;}}
  if(s.endsWith('ь'))s=s.slice(0,-1);
  return s||w;
}

const EN_SUFFIX = [['ational','ate'],['tional','tion'],['iveness','ive'],['fulness','ful'],['ousness','ous'],['ization','ize'],['ation','ate'],['ments','ment'],['ement',''],['ness',''],['ingly',''],['edly',''],['ing',''],['ies','y'],['ied','y'],['ers','er'],['ed',''],['es',''],['ly',''],['s','']];

export function stemEn(word){
  const w=word.toLowerCase();
  if(w.length<4)return w;
  for(const [suf,rep] of EN_SUFFIX){if(w.endsWith(suf)&&w.length-suf.length>=3)return w.slice(0,w.length-suf.length)+rep;}
  return w;
}

export function stem(word){return /[а-яё]/.test(String(word).toLowerCase())?stemRu(word):stemEn(word);}
